RAKE_TRACE_MAX_TRACE_TIME = 10 * 60


class StartTtiTrace(Query):
    def __init__(self, req, resp):
        super(StartTtiTrace, self).__init__(req, resp)

    def fill_req_msg(self, report_name, meas_period):
        # type: (int, int) -> None
        self.req_msg.contextId = (get_context_id() << 16) | (report_name & 0xffff)
        self.req_msg.procedureId = get_procedure_id()

        self.req_msg.reportName = report_name
        self.req_msg.periodicityScale = EBrowserPeriodicityScale.EBrowserTimeScale_SubFrame
        self.req_msg.reportPeriod = meas_period
        self.req_msg.startSfn = 0xffffffff
        self.req_msg.reportingDuration = 0
        self.req_msg.reportGranularityScale = 1

        # this 'if' reverts above changes back to original values from BrowserStartGeneralReportReq !!!!!
        # so maybe it calls for a separate class? or something?
        if report_name == EBrowserObjectName.EBrowserObjectName_HsupaL2Trace:
            self.req_msg.periodicityScale = EBrowserPeriodicityScale.EBrowserTimeScale_RadioFrame
            self.req_msg.startSfn = 0xfff0
            self.req_msg.reportGranularityScale = 0

        if report_name == EBrowserObjectName.EBrowserObjectName_PicRadecTtiTrace:
            self.req_msg.periodicityScale = EBrowserPeriodicityScale.EBrowserTimeScale_mSec
            self.req_msg.numberOfAssociatedObjects = 1
            self.req_msg.dynamicData[0] = EBrowserObjectName.EBrowserObjectName_Cpu
            self.req_msg.dynamicData[1] = 1

        elif report_name == EBrowserObjectName.EBrowserObjectName_MacHsTtiTrace:
            self.req_msg.numberOfAssociatedObjects = 1
            self.req_msg.dynamicData[0] = EBrowserObjectName.EBrowserObjectName_MacHs
            self.req_msg.dynamicData[1] = 1

        elif report_name in (EBrowserObjectName.EBrowserObjectName_RakeTtiMeasurement,
                             EBrowserObjectName.EBrowserObjectName_RakeTrace,
                             EBrowserObjectName.EBrowserObjectName_TupTtiTrace,
                             EBrowserObjectName.EBrowserObjectName_FpTtiTrace,
                             EBrowserObjectName.EBrowserObjectName_HsdpaEncoderMachsTrace,
                             EBrowserObjectName.EBrowserObjectName_HsdpaL1TraTxTrace,
                             EBrowserObjectName.EBrowserObjectName_DecDecoderRakeL2Trace,
                             EBrowserObjectName.EBrowserObjectName_DecDecoderPicTrace,
                             EBrowserObjectName.EBrowserObjectName_NonHsdpaL1TraTxTrace,
                             EBrowserObjectName.EBrowserObjectName_HsupaL2CellTrace,
                             EBrowserObjectName.EBrowserObjectName_HsupaL2UserTrace,
                             EBrowserObjectName.EBrowserObjectName_EvamCmdTrace,
                             EBrowserObjectName.EBrowserObjectName_EncoderTtiTrace,
                             EBrowserObjectName.EBrowserObjectName_HsupaL2MasterTrace,
                             EBrowserObjectName.EBrowserObjectName_HsupaL2SlaveTrace,
                             EBrowserObjectName.EBrowserObjectName_EncodedDataTrace):
            self.req_msg.numberOfAssociatedObjects = 0

    def _handle_response(self):
        status = self.resp_msg.status
        if status != 0:
            LOGGER.warning('Trace collection start error (BrowserStartGeneralReportResp with status {}) '.format(status))
            # raise MessageStatusError

    def _decide_if_complete(self):
        pass


class StopTtiTrace(Query):
    def __init__(self, req, resp):
        super(StopTtiTrace, self).__init__(req, resp)

    def fill_req_msg(self, report_name, context_id, procedure_id):
        # type: (int, int, int) -> None
        self.req_msg.contextId = context_id
        self.req_msg.procedureId = procedure_id
        self.req_msg.reportName = report_name

    def _handle_response(self):
        status = self.resp_msg.status
        if status != 0:
            LOGGER.warning('Trace collection stop error (BrowserStopGeneralReportResp with status {}) '.format(status))

    def _decide_if_complete(self):
        pass


class TTITraceCollector(BaseTraceCollector):
    def __init__(self, connection):
        super(TTITraceCollector, self).__init__(connection)

    def find_target_board_cpu(self, cell_id):
        target_board, target_cpu = _get_target_board_cpu_for_cell_and_report(cell_id, self.report_name, self.connection)
        if not target_cpu:
            LOGGER.warning('Could not determine board and cpu for collecting {} for cell {}'.format(self.trace_name,
                                                                                                    cell_id)
                           )
            return

        self.board = target_board
        self.cpu = target_cpu
        LOGGER.info('{} will be collected from 0x{:x}{:x}'.format(self.trace_name, self.board, self.cpu))

    def prepare_query_managers(self):
        # type: () -> BrowserGeneralReportIndSink
        if not self.board:
            return
        board, cpu = self.board, self.cpu
        start_query = StartTtiTrace(BrowserStartGeneralReportReq(board, cpu), BrowserStartGeneralReportResp())
        start_query.fill_req_msg(self.report_name, self.meas_period)

        context_id, procedure_id = start_query.req_msg.contextId, start_query.req_msg.procedureId

        stop_query = StopTtiTrace(BrowserStopGeneralReportReq(board, cpu), BrowserStopGeneralReportResp())
        stop_query.fill_req_msg(self.report_name, context_id, procedure_id)

        self.start_qm = BasicQueryManager(start_query, self.connection)
        self.stop_qm = BasicQueryManager(stop_query, self.connection)
        self.ind_m = BrowserGeneralReportIndSink(cookie=(BrowserGeneralReportInd.id, context_id, procedure_id))


def _prepare_machs_tti_trace_collector(cell_id, connection):
    # type: (int, str) -> TTITraceCollector
    meas_period = 10  # ms
    report_name = EBrowserObjectName.EBrowserObjectName_MacHsTtiTrace

    collector = TTITraceCollector(connection)
    collector.set_parameters(
        report_name=report_name,
        meas_period=meas_period
    )
    collector.find_target_board_cpu(cell_id)
    collector.prepare_query_managers()

    return collector


def _get_target_board_cpu_for_cell_and_report(cell_id, report_name, connection):
    """
    1. Find all (board, cpu) pairs for which given service is available
    2. For above pairs, find the one with `cell_id` allocated
    3. Collect traces
    """
    candidate_board_and_cpu_ids = ServiceInterface(connection).get_board_cpu_pairs_with_given_service_or_message(report_name)

    target_board, target_cpu = None, None
    for board, cpu in candidate_board_and_cpu_ids:
        trial_cell_ids = CellListInterface(connection).get_cell_ids(board, cpu)
        if cell_id in trial_cell_ids:
            target_board, target_cpu = board, cpu
            break

    return target_board, target_cpu


def _collect_machs_tti_trace(cell_id, trace_time, output_path, trace_alias, connection):
    # type: (int, int, str, str, str) -> None
    collector = _prepare_machs_tti_trace_collector(cell_id, connection)
    if collector:
        TRACE_STORE.add(collector, trace_alias)
        collector.start()
        sleep(trace_time)
        collector.stop()
        collector.save_traces(output_path)


# RAKE TRACE
def _get_target_board_cpu_ids_for_rake_trace(report_name, connection):
    candidate_board_and_cpu_ids = ServiceInterface(connection).get_board_cpu_pairs_with_given_service_or_message(report_name)

    target_board_cpu_list = []
    for board, cpu in candidate_board_and_cpu_ids:
        user_ids = UserListInterface(connection).get_user_ids(board, cpu)
        if user_ids:
            LOGGER.debug('Found user {}'.format(user_ids[0]))
            target_board_cpu_list.append((board, cpu))

    return target_board_cpu_list


class RakeTraceIndSink(BrowserGeneralReportIndSink):
    def __init__(self, cookie):
        super(RakeTraceIndSink, self).__init__(cookie)
        self.all_inds_dict = defaultdict(list)

    def digest(self, byte_stream):
        msg = BrowserGeneralReportInd().deserialize(byte_stream)

        status_ok = self._check(byte_stream)
        if status_ok:
            sender_board = msg.header.sender.board
            sender_cpu = msg.header.sender.cpu
            self.all_inds_dict[(sender_board, sender_cpu)].append(byte_stream)


class RakeTraceCollector(BaseTraceCollector):
    """
    Apparently, there are two types of Rake Trace sources: DCH Rake Slave and DCH Rake Master. Rake Trace should be
    collected from the slave but it's hard to determine from which one.
    The algorithm is therefore as follows:
    1. Find (board, cpu) pairs where EBrowserObjectName.EBrowserObjectName_RakeTrace is available
    2. Filter out only those pairs, for which User is allocated (target_board_cpu_list)
    3. For each (board, cpu) in target_board_cpu_list send BrowserStartGeneralReportReq
    4. Collect traces for each (board, cpu) separately (all_inds_dict)
    5. For (board, cpu) in target_board_cpu_list send BrowserStopGeneralReportReq
    6. Save output file only for (board, cpu)s with number of collected traces > 1 (it's 1 for Rake Master)
    """
    def __init__(self, connection):
        super(RakeTraceCollector, self).__init__(connection)
        self.target_board_cpu_list = []

        self.report_name = EBrowserObjectName.EBrowserObjectName_RakeTrace
        self.trace_name = get_browser_object_name(self.report_name)

    def find_target_board_cpu(self):

        target_board_cpu_list = _get_target_board_cpu_ids_for_rake_trace(self.report_name, self.connection)
        if not target_board_cpu_list:
            LOGGER.warning('Could not determine board and cpu for collecting Rake traces')
            return

        self.target_board_cpu_list = target_board_cpu_list

        LOGGER.debug('Attempt to collect {} from {}'.format(
            self.trace_name,
            sorted(['0x{:x}{:x}'.format(board, cpu) for board, cpu in target_board_cpu_list])
        ))

    def prepare_query_managers(self):
        if not self.target_board_cpu_list:
            return
        board, cpu = self.target_board_cpu_list[0]
        start_query = StartTtiTrace(BrowserStartGeneralReportReq(board, cpu), BrowserStartGeneralReportResp())
        start_query.fill_req_msg(self.report_name, self.meas_period)

        context_id, procedure_id = start_query.req_msg.contextId, start_query.req_msg.procedureId

        stop_query = StopTtiTrace(BrowserStopGeneralReportReq(board, cpu), BrowserStopGeneralReportResp())
        stop_query.fill_req_msg(self.report_name, context_id, procedure_id)

        self.start_qm = BasicQueryManager(start_query)
        self.stop_qm = BasicQueryManager(stop_query)
        self.ind_m = RakeTraceIndSink(cookie=(BrowserGeneralReportInd.id, context_id, procedure_id))

    def start(self):
        self.start_time = datetime.now()
        if not self:
            LOGGER.debug('Start request not sent')
            return
        for board, cpu in self.target_board_cpu_list:
            LOGGER.debug('Sending start request for 0x{:x}{:x}'.format(board, cpu))
            self.start_qm.query.req_msg.header.receiver.board = board
            self.start_qm.query.req_msg.header.receiver.cpu = cpu
            self.start_qm.send_request_and_wait_for_response()

    def stop(self):
        self.stop_time = datetime.now()
        if not self:
            LOGGER.debug('Stop request not sent')
            return

        for board, cpu in self.target_board_cpu_list:
            LOGGER.debug('Sending stop request for 0x{:x}{:x}'.format(board, cpu))
            self.stop_qm.query.req_msg.header.receiver.board = board
            self.stop_qm.query.req_msg.header.receiver.cpu = cpu
            self.stop_qm.send_request_and_wait_for_response()

    def save_traces(self, output_path, as_zip=True):
        if not self:
            LOGGER.warning('No {} collected'.format(self.trace_name))
            return

        board, cpu = self.target_board_cpu_list[0]
        sw_version = MiscInterface(self.connection).get_browser_sw_version(board, cpu)
        for board_cpu_tuple, inds in self.ind_m.all_inds_dict.items():
            board, cpu = board_cpu_tuple
            if len(inds) > 1:
                all_traces = prepare_rake_traces_for_export_to_txt_file(inds)
                file_name = build_trace_file_name(board, cpu, self.trace_name, self.stop_time)
                file_path = os.path.join(output_path, file_name)
                file_header = build_trace_file_header(len(all_traces), self.report_name, sw_version,
                                                      self.start_time, self.stop_time)

                in_memory_txt_file = build_in_memory_file(file_header, all_traces)

                saver = ZipSaver if as_zip else TxtSaver
                return saver(in_memory_txt_file, file_path).save()

            else:
                LOGGER.debug('No traces collected for 0x{:x}{:x}'.format(board, cpu))

    def __bool__(self):
        return bool(self.target_board_cpu_list)

    __nonzero__ = __bool__


def _prepare_rake_trace_collector(output_path, connection):
    meas_period = 10  # ms

    collector = RakeTraceCollector(connection)
    collector.set_parameters(
        meas_period=meas_period,
        output_path=output_path
    )
    collector.find_target_board_cpu()
    collector.prepare_query_managers()
    return collector


def _collect_rake_trace(trace_time, output_path, trace_alias, connection):
    # type: (int, str, str, ...) -> None
    if trace_time > RAKE_TRACE_MAX_TRACE_TIME:
        LOGGER.error('Too long trace_time ({} sec). Maximum is {} minutes)'.format(
            trace_time, int(RAKE_TRACE_MAX_TRACE_TIME / 60.0))
        )
        return

    collector = _prepare_rake_trace_collector(output_path, connection)
    if collector:
        TRACE_STORE.add(collector, trace_alias)
        collector.start()
        sleep(trace_time)
        collector.stop()
        collector.save_traces(output_path)
